    fun covers(ranges: IntArray, codePoint: Int): Boolean {
        var lo = 0
        var hi = ranges.size / 2 - 1
        while (lo <= hi) {
            val mid = (lo + hi) ushr 1
            when {
                codePoint < ranges[2 * mid] -> hi = mid - 1
                codePoint > ranges[2 * mid + 1] -> lo = mid + 1
                else -> return true
            }
        }
        return false
    }
